fn solve(queries: Vec<i8>) -> Vec<i8> {
    let mut results = Vec::with_capacity(queries.len());
    for n in queries {
        let x = if n >= 4 {
            // If n is already at least 4, we only need to add 0 or 1
            // to make it even, i.e. n % 2.
            n % 2
        } else {
            // If n is 2 or 3, we must bring it up to 4.
            4 - n
        };
        results.push(x);
    }
    results
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_all_cases() {
        // n < 4
        assert_eq!(solve(vec![2]), vec![2]); // 2 -> need 2 more to reach 4
        assert_eq!(solve(vec![3]), vec![1]); // 3 -> need 1 more to reach 4

        // n >= 4, odd/even adjustment
        assert_eq!(solve(vec![4]), vec![0]); // already even and ≥ 4
        assert_eq!(solve(vec![5]), vec![1]); // odd, add 1 to make even
        assert_eq!(solve(vec![6]), vec![0]); // even
        assert_eq!(solve(vec![7, 8, 9]), vec![1, 0, 1]);

        // mixed
        let input = vec![2, 3, 4, 5, 10];
        let output = vec![2, 1, 0, 1, 0];
        assert_eq!(solve(input), output);
    }
}